// Port of lib/prism/parse_result/errors.rb's Errors#format - renders a
// parse result's errors as source + inline carets, e.g.:
//
//   alias $a $1
//            ^~ invalid argument being passed to `alias`; can't make alias
//
// Used to compare target_js_uni's own errors directly against the
// test/prism/errors/*.txt fixtures (which were generated by this same
// renderer running against the real parser) - a forward render-and-compare
// instead of writing a second, independent parser for the caret format.
//
// Assumes `line:` is never set to anything but the default (1) - none of
// the error fixtures use it.

function byteLength(text) {
  return Buffer.byteLength(text, "utf8");
}

/**
 * @param {string} source the exact source that was parsed (no trailing
 *   newlines - see stripCarets() below, which produces it)
 * @param {{start: number, end: number, message: string}[]} errors byte
 *   offsets, in parse order
 * @param {number[]} offsets byte offsets of each line start (as produced by
 *   envelopeOffsetsToBytes())
 */
export function errorsFormat(source, errors, offsets) {
  function lineFor(offset) {
    let index = offsets.findIndex((o) => o > offset);
    if (index === -1) index = offsets.length;
    return index; // 1-indexed line number (offsets[0] is always 0, line 1)
  }
  function columnFor(offset, line) {
    return offset - offsets[line - 1];
  }

  const errorLines = new Map();
  for (const error of errors) {
    const startLine = lineFor(error.start);
    const endLine = lineFor(error.end);
    const annotated = {
      error,
      startLine,
      endLine,
      startColumn: columnFor(error.start, startLine),
      endColumn: columnFor(error.end, endLine),
    };
    for (let line = startLine; line <= endLine; line++) {
      if (!errorLines.has(line)) errorLines.set(line, []);
      errorLines.get(line).push(annotated);
    }
  }

  let sourceLines = source.length === 0 ? [] : source.split(/(?<=\n)/);
  if (errorLines.has(sourceLines.length + 1)) sourceLines = [...sourceLines, ""];

  let out = "";
  sourceLines.forEach((line, index) => {
    const lineNumber = index + 1;
    out += line.endsWith("\n") ? line : line + "\n";

    for (const { error, startLine, endLine, startColumn, endColumn } of errorLines.get(lineNumber) ?? []) {
      if (lineNumber === startLine) {
        let text = " ".repeat(startColumn) + "^";
        if (startLine === endLine) {
          if (startColumn !== endColumn) text += "~".repeat(endColumn - startColumn - 1);
          text += " " + error.message;
        } else {
          text += "~".repeat(byteLength(line) - startColumn);
        }
        out += text + "\n";
      } else if (lineNumber === endLine) {
        out += "~".repeat(endColumn) + " " + error.message + "\n";
      } else {
        out += "~".repeat(byteLength(line)) + "\n";
      }
    }
  });

  return out + "\n";
}

/**
 * Reconstructs the source a fixture's carets were rendered against: strip
 * every caret-annotation line (leading whitespace then `^`), then strip all
 * trailing newlines - mirrors assert_errors's own
 * `expected.lines.grep_v(/^\s*\^/).join.gsub(/\n*\z/, "")` exactly.
 */
export function stripCarets(text) {
  const kept = text.split(/(?<=\n)/).filter((line) => !/^\s*\^/.test(line));
  return kept.join("").replace(/\n*$/, "");
}
